import os
from typing import Any, Dict, List, Optional

import boto3
from botocore.exceptions import BotoCoreError, ClientError


def _normalize_response(response: Dict[str, Any]) -> Dict[str, Any]:
    blocks = response.get("Blocks", []) or []
    elements: List[Dict[str, Any]] = []

    for block in blocks:
        geometry = block.get("Geometry", {}) or {}
        bbox = geometry.get("BoundingBox", {}) or {}
        polygon = geometry.get("Polygon", []) or []

        elements.append(
            {
                "id": block.get("Id"),
                "block_type": block.get("BlockType"),
                "text": block.get("Text"),
                "confidence": block.get("Confidence"),
                "page": block.get("Page"),
                "relationships": block.get("Relationships", []),
                "geometry": {
                    "bounding_box": {
                        "left": bbox.get("Left"),
                        "top": bbox.get("Top"),
                        "width": bbox.get("Width"),
                        "height": bbox.get("Height"),
                    },
                    "polygon": polygon,
                },
                "selection_status": block.get("SelectionStatus"),
                "entity_types": block.get("EntityTypes", []),
            }
        )

    return {
        "document_metadata": response.get("DocumentMetadata", {}),
        "job_status": response.get("JobStatus"),
        "elements": elements,
    }


def extract_layout_elements(
    *,
    document_bytes: Optional[bytes] = None,
    s3_bucket: Optional[str] = None,
    s3_key: Optional[str] = None,
    feature_types: Optional[List[str]] = None,
    region_name: Optional[str] = None,
) -> Dict[str, Any]:
    """
    Extract OCR and layout elements from a document using AWS Textract.

    Provide either `document_bytes` or both `s3_bucket` and `s3_key`.

    Returns a normalized dictionary containing blocks/elements such as:
    TEXT, LINE, WORD, TABLE, CELL, KEY_VALUE_SET, SIGNATURE, SELECTION_ELEMENT, etc.
    """
    if feature_types is None:
        feature_types = ["TABLES", "FORMS"]

    client = boto3.client("textract", region_name=region_name)

    try:
        if document_bytes is not None:
            response = client.analyze_document(
                Document={"Bytes": document_bytes},
                FeatureTypes=feature_types,
            )
        elif s3_bucket and s3_key:
            response = client.analyze_document(
                Document={"S3Object": {"Bucket": s3_bucket, "Name": s3_key}},
                FeatureTypes=feature_types,
            )
        else:
            raise ValueError("Provide either document_bytes or both s3_bucket and s3_key.")

        return _normalize_response(response)

    except (BotoCoreError, ClientError) as exc:
        raise RuntimeError(f"AWS Textract extraction failed: {exc}") from exc
